SELECT t.* FROM ( select hd.payment_req_id, hd.company_id, hd.document_type, hd.document_category, hd.business_type, hd.payment_req_number, hd.payment_req_date, hd.payment_req_status, hd.apply_pay_date, hd.amount, hd.currency, hd.description, hd.process_instance_id, hd.object_version_number, hd.request_id, hd.program_id, hd.created_by, hd.creation_date, hd.last_updated_by, hd.last_update_date, hd.last_update_login, hd.bp_bank_account_id, hd.bp_bank_name, hd.bp_bank_branch_name, hd.bp_bank_account_num, hd.bp_bank_account_name, hd.source_doc_id, hd.source_doc_type, hd.deduct_flag, hd.source_doc_line_id, hd.deduct_write_off_flag, hd.pay_amount, hd.funding_plan_id, hd.transfer_status, hd.con_end_task, hd.eft_process_instance_id, hd.trial, hd.recheck, hd.proposed_launch_date, hd.project_name, hd.finance_amount, hd.sum_toufang_amount, hd.contract_balance, hd.employee_id, hd.unit_id, hd.plan_id, hd.plan_date_amount, hd.loan_type, hd.payment_type, hd.payment_approved_status, hd.financial_agent_id, hd.financial_unit_id, hd.remaining_amount, hd.accumulated_payment_amount, hd.actual_pay_date, hd.payment_process_instance_id, hd.contract_currency_id, hd.actual_hd_pay_amount, hd.send_flag, hd.loan_total_amount, hd.source_contract_id, hd.bank_account_id, hd.bp_id, ln.payment_bp_type, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.CODE = 'PAYMENT_BP_TYPE' and v.code_value = ln.payment_bp_type) payment_bp_type_n, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = hd.bp_id) payment_bp_name, hd.authority_rule_string, hd.payment_status, hd.com_cost_rate, hd.other, hd.post_itfc_flag, hd.post_approved_date, hd.itfc_document, hd.post_itfc_code, hd.post_itfc_msg, hd.payment_method, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = hd.payment_method ) payment_method_n, (hd.AMOUNT - nvl((select sum(dt.DEDUCT_AMOUNT) from CSH_PAYMENT_REQ_LN cprl, CSH_PAYMENT_REQ_DT dt where cprl.PAYMENT_REQ_ID = hd.PAYMENT_REQ_ID and cprl.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID), 0)) as after_deduct_amount, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH_PAYMENT_HD_STATUS' AND scb.CODE_ID = scv.CODE_ID and scv.value = hd.payment_req_status ) payment_req_status_n, (select fc.currency_name from fnd_currency fc where fc.currency_code = hd.currency) currency_n, ( select hdt.description from hls_document_type hdt where hdt.document_type = hd.document_type ) document_type_n from csh_payment_req_hd hd left join ( SELECT ll.PAYMENT_REQ_ID, cc.PAYMENT_BP_TYPE FROM csh_payment_req_ln ll, CON_CONTRACT cc where ll.payment_req_ln_id = ( select max(l.payment_req_ln_id) from csh_payment_req_ln l where l.payment_req_id = ll.payment_req_id ) and ll.SOURCE_DOC_ID = cc.CONTRACT_ID ) ln on ln.payment_req_id = hd.payment_req_id) t
t.SOURCE_CONTRACT_ID is null
AND t.payment_req_status = #{paymentReqStatus}
AND t.payment_req_number like #{paymentReqNumber}
and exists(select 1 from con_contract cc, CSH_PAYMENT_REQ_LN ln1 where ln1.PAYMENT_REQ_ID = t.PAYMENT_REQ_ID and cc.contract_id = ln1.source_doc_id and cc.contract_number like #{contractNumber})
AND t.payment_req_date >= #{paymentReqDateFrom}
AND t.payment_req_date <= #{paymentReqDateTo}
AND t.amount >= #{amountFrom}
AND t.amount <= #{amountTo}
AND t.bp_name like #{bpName}
and exists(select 1 from con_contract cc,CSH_PAYMENT_REQ_LN ln1,hls_bp_master hbm where ln1.PAYMENT_REQ_ID = t.PAYMENT_REQ_ID and cc.contract_id = ln1.source_doc_id and cc.BP_ID_TENANT = hbm.BP_ID and hbm.bp_name like #{bpTenantName})
and exists(select 1 from con_contract cc,CSH_PAYMENT_REQ_LN ln1,hls_bp_master hbm where ln1.PAYMENT_REQ_ID = t.PAYMENT_REQ_ID and cc.contract_id = ln1.source_doc_id and cc.factory_id = hbm.BP_ID and hbm.bp_name like #{factoryIdName})
AND t.bp_id = #{bpId}
AND t.payment_req_id = #{paymentReqId}
AND ('Y' = #{modifyFlag} AND t.payment_req_status != 'APPROVED')
AND ('Y' = #{paymentFlag} AND t.payment_req_status = 'APPROVED')
AND ( ('Y' = #{reverseFlag} and EXISTS (select 1 from csh_payment_req_ln ll where ll.payment_req_id = t.payment_req_id and ifnull(ll.submit_flag,'N') = 'Y')) OR ('N' = #{reverseFlag} and EXISTS (select 1 from csh_payment_req_ln ll where ll.payment_req_id = t.payment_req_id and ifnull(ll.submit_flag,'N') = 'N')) )
ORDER BY t.payment_req_number desc

select * from ( SELECT cprd.payment_req_id, cprd.document_category, cprd.payment_req_number, cprd.payment_req_date, cprd.company_id, (SELECT scv.DESCRIPTION FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_REQ_STATUS' AND scb.CODE_ID = scv.CODE_ID and scv.value = cprd.payment_req_status) payment_req_status_desc, cprd.payment_req_status, nvl(cprd.amount,0)amount, (select fc.currency_name from fnd_currency fc where fc.currency_code = cprd.currency) currency_name, cprd.description, (select nvl(wm_concat(DISTINCT(fe.name)),'--') from sys_user su ,sys_user_allocation sta,fnd_employee_assigns fea,fnd_employee fe where su.user_id = sta.user_id and fea.employee_assign_id = sta.employee_assign_id and fea.employee_id = fe.employee_id and su.USER_ID = cprd.CREATED_BY ) USER_NAME, -- (select su.USER_NAME from sys_user su where su.USER_ID = cprd.CREATED_BY) USER_NAME, CASE WHEN ( SELECT sum( nvl(l.amount, 0) - nvl(l.amount_paid, 0) ) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) = 0 THEN '已支付' WHEN ( SELECT sum( nvl(l.amount, 0) - nvl(l.amount_paid, 0) ) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) < ( SELECT sum(nvl(l.amount, 0)) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) THEN '部分支付' WHEN ( SELECT sum( nvl(l.amount, 0) - nvl(l.amount_paid, 0) ) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) = ( SELECT sum(nvl(l.amount, 0)) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) THEN '未支付' END AS payment_flag_desc, CASE WHEN ( SELECT sum( nvl(l.amount, 0) - nvl(l.amount_paid, 0) ) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) = 0 THEN 'FULL' WHEN ( SELECT sum( nvl(l.amount, 0) - nvl(l.amount_paid, 0) ) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) < ( SELECT sum(nvl(l.amount, 0)) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) THEN 'PARTIAL' WHEN ( SELECT sum( nvl(l.amount, 0) - nvl(l.amount_paid, 0) ) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) = ( SELECT sum(nvl(l.amount, 0)) FROM csh_payment_req_ln l WHERE l.payment_req_id = cprd.payment_req_id ) THEN 'NOT' END AS payment_flag FROM csh_payment_req_hd cprd) t1 where 1=1 and t1.document_category='CSH_PAYMENT_REQ' and t1.company_id=#{request.companyId}
and t1.payment_req_id =#{payment_req_id,jdbcType=BIGINT}
and t1.payment_req_number LIKE concat(concat('%',#{payment_req_number}),'%')
and t1.payment_req_status in
#{payment_req_status}
and t1.payment_flag in
#{payment_flag}
and(((#{payment_amount_1}='Y' and t1.amount>=0 and t1.amount<1000000) or (#{payment_amount_2}='Y' and t1.amount>=1000000 and t1.amount<5000000 ) or (#{payment_amount_3}='Y' and t1.amount>=5000000 and t1.amount<10000000 ) or(#{amount_from} is not null and #{amount_to} is not null and t1.amount>=#{amount_from} and t1.amount<=#{amount_to} ) or(#{amount_to} is not null and #{amount_from} is null and t1.amount<=#{amount_to} ) or(#{amount_from} is not null and #{amount_to} is null and t1.amount>=#{amount_from} ) ) or(nvl(#{payment_amount_1},'N')!='Y' and nvl(#{payment_amount_2},'N')!='Y' and nvl(#{payment_amount_3},'N')!='Y' and #{amount_from} is null and #{amount_to} is null )) order by t1.payment_req_number

SELECT '广东粤海融资租赁有限公司' as company_name, (select int_rate from prj_quotation pq where pq.quotation_id = cc.quotation_id) int_rate, (select XIRR from prj_quotation pq where pq.quotation_id = cc.quotation_id) xirr, (select IRR from prj_quotation pq where pq.quotation_id = cc.quotation_id) irr, (select LEASE_TERM from prj_quotation pq where pq.quotation_id = cc.quotation_id) lease_term, (select FINANCE_NOTE from PRJ_PROJECT pp where pp.project_id = cc.project_id ) finance_note, cc.contract_id, reqhd.source_contract_id, reqhd.payment_req_id, nvl( reqhd.send_flag, 'N' ) send_flag, reqhd.CONTRACT_CURRENCY_ID, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = reqhd.CONTRACT_CURRENCY_ID ) CONTRACT_CURRENCY, reqhd.PAYMENT_PROCESS_INSTANCE_ID, cc.contract_number funding_plan_number, reqhd.payment_req_date, reqhd.payment_req_number, cc.contract_number payment_number, cc.contract_name contract_name, reqhd.PROPOSED_LAUNCH_DATE, cc.contract_number funding_plan_id_n, reqhd.funding_plan_id, reqhd.LOAN_TOTAL_AMOUNT, ( SELECT pp.contract_number FROM prj_project pp WHERE pp.project_id = cc.project_id ) contract_number,
reqhd.bp_id, (select hb.bp_name from hls_bp_master hb where hb.bp_id=reqhd.bp_id) bp_name, reqhd.PROJECT_NAME, reqhd.FINANCE_AMOUNT, (select nvl(sum(nvl(h.LOAN_TOTAL_AMOUNT,0)),0) from csh_payment_req_hd h where h.source_doc_id = reqhd.SOURCE_DOC_ID AND h.PAYMENT_APPROVED_STATUS = 'PAID' and h.LOAN_TYPE = 'ROUTINE')SUM_TOUFANG_AMOUNT, (case when (select h.LOAN_TYPE from csh_payment_req_hd h where h.payment_req_id = #{paymentReqId}) = 'TARIFF' then null else (reqhd.FINANCE_AMOUNT - (select nvl(sum(nvl(h.LOAN_TOTAL_AMOUNT,0)),0) from csh_payment_req_hd h where h.source_doc_id = reqhd.SOURCE_DOC_ID AND h.PAYMENT_APPROVED_STATUS = 'PAID' and h.LOAN_TYPE != 'TARIFF')) end) CONTRACT_BALANCE, reqhd.EMPLOYEE_ID, (SELECT distinct e.NAME FROM sys_user s, sys_user_allocation a, fnd_employee e, fnd_employee_assigns fa WHERE s.user_id = a.user_id AND a.EMPLOYEE_ASSIGN_ID = fa.EMPLOYEE_ASSIGN_ID AND fa.EMPLOYEE_ID = e.EMPLOYEE_ID
and a.USER_ID=reqhd.EMPLOYEE_ID and fa.PRIMARY_POSITION_FLAG = 'Y') EMPLOYEE_ID_N, -- reqhd.unit_id, -- ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = reqhd.unit_id ) AS unit_id_n, reqhd.PLAN_ID, (SELECT ( SELECT b.start_date|| '~'|| b.end_date FROM jc_fund_plan_schedule b WHERE b.fill_year = a.fill_year AND b.fill_mon = a.fill_mon AND b.fill_week = a.fill_week ) value_name FROM jc_fund_filling a WHERE a.filling_id = reqhd.plan_id)plan_id_n, (SELECT reqhd.proposed_launch_date || '~' || ( SELECT nvl( sum( nvl( d.due_amount, 0 ) ), 0 ) FROM jc_fund_filling_detail d WHERE d.filling_id = a.filling_id AND d.item_code = 'LOAN_DELIVERY' AND d.fund_type = reqhd.proposed_launch_date ) plan_date_amount FROM jc_fund_filling a WHERE a.filling_id = reqhd.plan_id)plan_date_amount, ( SELECT pp.project_id FROM prj_project pp WHERE pp.project_id = reqhd.source_doc_id ) project_id, ( SELECT pp.INSURE_ID FROM prj_project_insure pp WHERE pp.project_id = reqhd.source_doc_id ) INSURE_ID, reqhd.LOAN_TYPE, reqhd.PAYMENT_TYPE, reqhd.PAYMENT_APPROVED_STATUS, reqhd.FINANCIAL_AGENT_ID, reqhd.FINANCIAL_UNIT_ID, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PAYMENT_APPROVED_STATUS' AND code_value = reqhd.PAYMENT_APPROVED_STATUS ) PAYMENT_APPROVED_STATUS_N, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH.LOAN_TYPE' AND code_value = reqhd.loan_type ) LOAN_TYPE_N, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH701_TRANSACTION_TYPE' AND code_value = reqhd.PAYMENT_TYPE ) PAYMENT_TYPE_N, ( SELECT fnd.NAME FROM fnd_employee fnd WHERE fnd.EMPLOYEE_ID = reqhd.FINANCIAL_AGENT_ID ) FINANCIAL_AGENT_ID_n, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = reqhd.FINANCIAL_UNIT_ID ) AS FINANCIAL_UNIT_ID_N, ( CASE WHEN reqhd.PAYMENT_TYPE = 'INVESTMENT' THEN (select sum(h.LOAN_TOTAL_AMOUNT) from csh_payment_req_hd h where h.source_doc_id = reqhd.SOURCE_DOC_ID AND h.PAYMENT_APPROVED_STATUS = 'PAID') ELSE NULL END ) ACCUMULATED_PAYMENT_AMOUNT, ( CASE WHEN reqhd.PAYMENT_TYPE = 'INVESTMENT' THEN (reqhd.FINANCE_AMOUNT - (select sum(h.LOAN_TOTAL_AMOUNT) from csh_payment_req_hd h where h.source_doc_id = reqhd.SOURCE_DOC_ID AND h.PAYMENT_APPROVED_STATUS = 'PAID')) ELSE NULL END ) REMAINING_AMOUNT, reqhd.ACTUAL_PAY_DATE, ( CASE
WHEN ( SELECT COUNT(*) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.CONTRACT_ID AND CCC.CF_ITEM IN ( 0 )) > 0 THEN 'Y' ELSE 'N' END ) item_Flag, reqhd.CURRENCY, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = reqhd.CURRENCY ) CURRENCY_n, reqhd.actual_hd_pay_amount, (select pp.REF_PROJECT_ID from prj_project pp where pp.project_id=reqhd.SOURCE_DOC_ID) ref_project_id, reqhd.AUTHORITY_RULE_STRING, reqhd.com_cost_rate,
pp.HOST_PROJECT_MANAGER, (SELECT a.description FROM sys_user a WHERE a.user_id=pp.host_project_manager) host_project_manager_n, pp.ASSIST_PROJECT_MANAGER, (select s.description from sys_user s where s.user_id = pp.assist_project_manager) assist_project_manager_n, pp.UNIT_ID, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.unit_id ) AS unit_id_n, (select APPROVAL_NUMBER from prj_project_approval t where t.project_id = to_char(pp.project_id) and t.data_class = 'NORMAL' and rownum =1) APPROVAL_NUMBER, ( SELECT nvl( reqhd.LOAN_TOTAL_AMOUNT, 0 ) - nvl( sum( lnba.actual_payment_amount ), 0 ) FROM csh_pay_req_ln_bank_account lnba, csh_payment_req_ln ln WHERE lnba.PAYMENT_REQ_LN_ID = ln.PAYMENT_REQ_LN_ID AND ln.payment_req_id = reqhd.PAYMENT_REQ_ID ) unpaid, ( SELECT decode(count(fa.attachment_id), 0, 1, count(fa.attachment_id)) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam, csh_payment_attachment cpa WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'csh_payment_attachment' AND cpa.csh_attcahment_id = fam.table_pk_value and cpa.payment_req_id = reqhd.PAYMENT_REQ_ID ) attachment_count FROM csh_payment_req_hd reqhd left join con_contract cc
on reqhd.source_contract_id=cc.contract_id left join prj_project pp on cc.project_id = pp.project_id
and cc.contract_id=#{contractId}
and reqhd.document_type = #{documentType}
and reqhd.payment_req_Id=#{paymentReqId}

select * from (SELECT cprh.PAYMENT_REQ_ID, cprh.PAYMENT_REQ_NUMBER, cc.contract_number, cprh.payment_req_status, cprh.PROPOSED_LAUNCH_DATE, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = pp.tenant_id ) AS bp_name, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS.WORK_FLOW_STATUS' AND code_value = cprh.payment_req_status ) payment_req_status_n, ( SELECT su.description FROM sys_user su WHERE su.user_id = cprh.created_by ) project_manager_id_n, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = cprh.CURRENCY ) CURRENCY_n, ( SELECT wm_concat(distinct i.description) FROM csh_payment_req_ln cprl,con_contract_cashflow ccc,hls_cashflow_item i WHERE cprl.payment_req_id = cprh.payment_req_id and cprl.SOURCE_DOC_LINE_ID = ccc.CASHFLOW_ID and i.cf_item = ccc.cf_item AND ccc.cf_type = i.cf_type) cf_item_n1, ( SELECT sum(ccc.due_amount) FROM csh_payment_req_ln cprl,con_contract_cashflow ccc WHERE cprl.payment_req_id = cprh.payment_req_id and cprl.SOURCE_DOC_LINE_ID = ccc.CASHFLOW_ID ) loan_total_amount1, cprl1.loan_total_amount,cprl1.cf_item_n, cprh.bp_id, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = cprh.bp_id ) AS bp_id_n, cprh.BP_BANK_ACCOUNT_NAME, cprh.BP_BANK_ACCOUNT_NAME as BP_BANK_ACCOUNT_NAME_N, cprh.BP_BANK_ACCOUNT_NUM FROM csh_payment_req_hd cprh LEFT JOIN con_contract cc ON cprh.SOURCE_CONTRACT_ID = cc.CONTRACT_ID LEFT JOIN prj_project pp ON cc.project_id = pp.project_id left join ( SELECT cprl.payment_req_id,wm_concat(distinct i.description) as cf_item_n ,sum(ccc.due_amount) as loan_total_amount FROM csh_payment_req_ln cprl,con_contract_cashflow ccc,hls_cashflow_item i WHERE cprl.SOURCE_DOC_LINE_ID = ccc.CASHFLOW_ID and i.cf_item = ccc.cf_item AND ccc.cf_type = i.cf_type group by cprl.payment_req_id) cprl1 on cprh.payment_req_id = cprl1.payment_req_id WHERE cprh.document_type = 'TARIFF_PAYMENT_REQ')V
1=1
and V.contract_number LIKE concat('%',concat(#{contractNumber},'%') )
and V.bp_name LIKE concat('%',concat(#{bpName},'%') )
and V.bp_id_n LIKE concat('%',concat(#{bpIdN},'%') )
and V.payment_req_number LIKE concat('%',concat(#{paymentReqNumber},'%') )
and V.project_manager_id_n LIKE concat('%',concat(#{projectManagerIdN},'%') )
and V.PROPOSED_LAUNCH_DATE >= #{proposedLaunchDateFrom}
and V.PROPOSED_LAUNCH_DATE <= #{proposedLaunchDateTo}
and V.payment_req_status = #{paymentReqStatus}
and V.PAYMENT_REQ_ID = #{paymentReqId}

SELECT
reqhd.other
FROM
csh_payment_req_hd reqhd
left  join con_contract  cc
on reqhd.source_contract_id=cc.contract_id



        and cc.contract_id=#{contractId}


        and reqhd.document_type = #{documentType}


        and reqhd.payment_req_Id=#{paymentReqId}

select v.* from (SELECT cprh.*, (select fc.currency_name from fnd_currency fc where fc.currency_code = cprh.currency) as currency_name, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PAYMENT_APPROVED_STATUS' AND code_value = cprh.PAYMENT_APPROVED_STATUS) AS PAYMENT_APPROVED_STATUS_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH.LOAN_TYPE' AND code_value = cprh.LOAN_TYPE) AS LOAN_TYPE_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH701_TRANSACTION_TYPE' AND code_value = cprh.payment_type) AS PAYMENT_TYPE_N, (cprh.AMOUNT - nvl((select sum(dt.DEDUCT_AMOUNT) from CSH_PAYMENT_REQ_LN cprl, CSH_PAYMENT_REQ_DT dt where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and cprl.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID), 0)) as after_deduct_amount, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS_WFL_STATUS' AND code_value = cprh.transfer_status) AS status_n, (SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = (select prj.employee_id from (select cprl.SOURCE_DOC_ID from CSH_PAYMENT_REQ_LN cprl where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and rownum = 1) line left join CON_CONTRACT con on con.CONTRACT_ID = line.SOURCE_DOC_ID left join PRJ_PROJECT prj on prj.PROJECT_ID = con.PROJECT_ID)) AS project_manager_name, ((cprh.AMOUNT - nvl((select sum(dt.DEDUCT_AMOUNT) from CSH_PAYMENT_REQ_LN cprl, CSH_PAYMENT_REQ_DT dt where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and cprl.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID), 0)) - (SELECT nvl(sum(lnba.actual_payment_amount), 0) FROM csh_pay_req_ln_bank_account lnba WHERE lnba.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID)) unpaid, (select prj.project_number from (select cprl.SOURCE_DOC_ID from CSH_PAYMENT_REQ_LN cprl where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and cprl.source_doc_category = 'CON_CONTRACT' and rownum = 1) line left join CON_CONTRACT con on con.CONTRACT_ID = line.SOURCE_DOC_ID left join PRJ_PROJECT prj on prj.PROJECT_ID = con.PROJECT_ID) project_number, (select con.project_id from (select cprl.SOURCE_DOC_ID from CSH_PAYMENT_REQ_LN cprl where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and cprl.source_doc_category = 'CON_CONTRACT' and rownum = 1) line left join CON_CONTRACT con on con.CONTRACT_ID = line.SOURCE_DOC_ID) project_id FROM csh_payment_req_hd cprh) v
and v.payment_req_number = #{paymentReqNumber}
and v.payment_approved_status = #{paymentApprovedStatus}
AND v.bp_name LIKE CONCAT(concat('%',#{bpName}),'%')
and v.proposed_launch_date = #{proposedLaunchDate}
and v.loan_total_amount = #{loanTotalAmount}
and v.proposed_launch_date >= to_date(#{proposedLaunchDateFrom}, 'yyyy-mm-dd')
and v.proposed_launch_date <= to_date(#{proposedLaunchDateTo}, 'yyyy-mm-dd')
order by v.payment_req_number desc

select v.* from (SELECT cprh.*, (select fc.currency_name from fnd_currency fc where fc.currency_code = cprh.currency) as currency_name, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PAYMENT_APPROVED_STATUS' AND code_value = cprh.PAYMENT_APPROVED_STATUS) AS PAYMENT_APPROVED_STATUS_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH.LOAN_TYPE' AND code_value = cprh.LOAN_TYPE) AS LOAN_TYPE_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH701_TRANSACTION_TYPE' AND code_value = cprh.payment_type) AS PAYMENT_TYPE_N, cprh.AMOUNT as after_deduct_amount, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS_WFL_STATUS' AND code_value = cprh.transfer_status) AS status_n, (SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = (select prj.employee_id from (select cprl.SOURCE_DOC_ID from CSH_PAYMENT_REQ_LN cprl where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and rownum = 1) line left join CON_CONTRACT con on con.CONTRACT_ID = line.SOURCE_DOC_ID left join PRJ_PROJECT prj on prj.PROJECT_ID = con.PROJECT_ID)) AS project_manager_name, ((cprh.AMOUNT - nvl((select sum(dt.DEDUCT_AMOUNT) from CSH_PAYMENT_REQ_LN cprl, CSH_PAYMENT_REQ_DT dt where cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID and cprl.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID), 0)) - (SELECT nvl(sum(lnba.actual_payment_amount), 0) FROM csh_pay_req_ln_bank_account lnba WHERE lnba.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID)) unpaid FROM csh_payment_req_hd cprh) v
V.payment_req_status in ('APPROVED')
and v.payment_req_number = #{paymentReqNumber}
and v.payment_approved_status = #{paymentApprovedStatus}
AND v.bp_name LIKE CONCAT(concat('%',#{bpName}),'%')
and v.proposed_launch_date = #{proposedLaunchDate}
and v.loan_total_amount = #{loanTotalAmount}
and v.proposed_launch_date >= to_date(#{proposedLaunchDateFrom}, 'yyyy-mm-dd')
and v.proposed_launch_date <= to_date(#{proposedLaunchDateTo}, 'yyyy-mm-dd')
order by v.payment_req_number desc
